    subtext_scribble: { style: "Frantic Scratch or Etching", effect: "Jittery alignment + Low opacity", content: ["don't look", "why?", "run", "nothing matters"] }
    data_tagging: { style: "Redacted Bar or Barcode Font", effect: "Pixel sorting + Glitch artifacts", content: ["Subject #404", "Value: $0.00", "Expired", "Censored"] }
  color_palette:
    decay_spectrum: ["#2B2B2B (Charcoal)", "#800000 (Dried Blood)", "#4B0082 (Bruise Purple)"]
    hazard_alert: ["#FF4500 (Safety Orange)", "#CCFF00 (Toxic Acid)", "#A9A9A9 (Concrete)"]
    textures: ["Burnt edges", "Caution tape", "Coffee rings", "Cracked screen", "Static noise"]

human_subject_analysis:
  female:
    face: { observe: "Identity", doodle: "Black censor bar over eyes, stitched lips", note: ["Blind consumer", "Mask", "Hollow"] }
    body: { observe: "Agency", doodle: "Puppet strings on limbs, fragile sticker", note: ["Controlled", "Doll", "Pose #34"] }
